    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 3, $q$A client has signed a proposal. Which statement is correct?$q$, $c$["The deal is Won because the client signed","The representative marks it Won","The sale still needs payment and Nova's verification; a signature alone is not a verified sale","Fulfilment has automatically started"]$c$::jsonb, 2, $e$Rep-reported close, signature, payment, verification and fulfilment are separate facts recorded by separate steps.$e$, false)
