  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 1, 1, $t$Your two-sentence opening$t$, $p$Write a two-sentence answer to "What does Nova do?" that starts with the prospect's customers, not with a deliverable, and promises nothing.$p$, $s$["Does the first sentence mention the prospect's customers or inquiries?","Is there any promise, number or guarantee? (There should be none.)","Does it end by asking for a short conversation rather than a purchase?"]$s$::jsonb, $m$I look at how a local business handles a new customer today — the phone, the website, the follow-up — and write down what I find, with evidence. Would you be open to a short conversation so I can see whether it is worth a closer look at your business?$m$)
