-- ---------------------------------------------------------------- prospecting-and-qualification
DO $academy$
DECLARE pid uuid; can_write boolean;
BEGIN
  SELECT id, (content_review_status = 'pending_owner_review' OR version < 2) INTO pid, can_write FROM academy_programs WHERE slug = 'prospecting-and-qualification';
  IF pid IS NULL THEN RAISE NOTICE 'program prospecting-and-qualification not found — run academy-migration-standalone.sql first'; RETURN; END IF;
  IF NOT can_write THEN RAISE NOTICE 'program prospecting-and-qualification content already approved — left unchanged'; RETURN; END IF;
  UPDATE academy_programs SET version = 2, content_review_status = 'pending_owner_review', learning_objectives = ARRAY[$o$Find businesses by observable, factual signals rather than guesses.$o$, $o$Source contacts legitimately and respect suppression rules.$o$, $o$Qualify with a short checklist before spending outreach time.$o$, $o$Record prospects without creating duplicates or crossing another representative's lead.$o$]::text[],
    practical_prompt = NULL, practical_rubric = '[]'::jsonb WHERE id = pid;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 1, $t$Facts, Not Guesses: Finding a Prospect Worth a Conversation$t$, ARRAY[$o$Recognise observable signals of a leaking customer journey.$o$, $o$Separate what you observed from what you assume.$o$]::text[], $b$Good prospecting starts with something you can actually see. Signals worth noting: a listing whose phone number or hours differ between sites; a website with no working contact form or booking path; a business that never seems to reply to reviews; a phone number that rings out with no voicemail; an "open" sign with nobody answering. Each is a fact you can write down.

What you do NOT know: how many customers the business loses, how much money that costs, or what happens inside their office. NEVER SAY "you're losing half your leads." SAY "I noticed your listing shows two different phone numbers — is that something you're aware of?"

HOW TO NOTE A SIGNAL: write it as an observation with where you saw it — "Google listing lists 203-555-0100; website footer lists 203-555-0199 (fictional numbers, seen today)". A note like that survives a manager's review; "seems disorganised" does not.

EXAMPLE (fictional): A plumbing company's site has a "Request a quote" form that returns an error page. That is worth mentioning once, kindly, as something you noticed — never as proof they lose work.

CHECKLIST: for each prospect you should be able to point to (1) one observable signal, (2) where you saw it, (3) a neutral question it lets you ask.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 2, $t$Sourcing Contacts Legitimately$t$, ARRAY[$o$Use only legitimate channels for contact details.$o$, $o$Respect do-not-contact and consent rules.$o$, $o$Avoid scraping and misuse of data.$o$]::text[], $b$Contact details must come from places the business itself publishes for contact: its website, its public listing, a referral, a chamber-of-commerce directory, a person you met. Do not scrape, buy lists of unknown origin, guess personal email addresses, or use data you were given for another purpose.

Two rules that protect everyone:
1. A business phone number published for customers may be called during business hours for a business-to-business conversation; texting a number needs the person's recorded consent first. Ask your manager if you are unsure — the system will not stop you from importing a list, but importing never creates consent.
2. If a contact is flagged do-not-contact, that flag is final. You cannot clear it; only the owner can, with documented written permission from the contact.

DUPLICATES: before you add a prospect, Nova's system checks whether that business (by website, phone or name and city) is already being worked by anyone. If it is, you will see a neutral message and no details — this prevents two representatives contacting the same owner and protects everyone's leads. If you believe the match is wrong, ask your manager; do not try to work around it.

SCRIPT for a referral: "[Name] suggested I reach out. I look at how local businesses handle new inquiries — would it be okay to ask you two questions about yours?"$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 3, $t$Qualifying Before You Pitch$t$, ARRAY[$o$Apply a four-point qualification checklist.$o$, $o$Identify who can authorise a diagnostic.$o$, $o$Decide honestly where to spend your time.$o$]::text[], $b$Before you invest effort, check four things loosely: (1) PROBLEM — is there a real, observable sign of a gap? (2) AUTHORITY — are you speaking with someone who can say yes (owner, manager, marketing lead)? (3) TIMING — is there any reason to act soon (new location, slow season, a run of poor reviews)? (4) REACHABILITY — do they answer through any channel?

You do not need all four to start a conversation. If none are true, spend your time elsewhere. Qualification is not about rejecting people; it is about being honest with yourself about where your effort will land.

WHAT TO RECORD when you move a lead to Qualified: a short summary in your own words (who they are and why they may benefit from a look) and whether you have spoken with the decision maker — yes, no, or unknown. The system requires both, because "Qualified" must mean something a manager can trust.

EXAMPLE (fictional): "Two-location dental office. Owner-dentist answers the phone himself. Google listing shows Saturday hours the website does not. Spoke to the office manager; the owner decides on vendors. Decision maker: no." That is a good qualified note — and it honestly says you have not reached the owner yet.

SCORE IT: rate each of the four 0 or 1, add them up, and contact the highest first.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 4, $t$Organising Your Prospect List$t$, ARRAY[$o$Keep a clean, honest pipeline.$o$, $o$Use the next-action habit.$o$, $o$Know what stale leads cost you.$o$]::text[], $b$A pipeline is only useful if it is truthful. Habits that keep it that way:
• Every open lead has a next action with a date. If it does not, you have forgotten it.
• Log an activity the moment it happens — a call, an email, a text, a visit — with a few words about what was said. The stage "Contacted" requires at least one real logged attempt; you cannot move a card there on a hunch.
• Close leads that are truly dead, with a reason code and a short note. A pipeline padded with leads you will never call hides the ones that matter, and managers can see stale leads.
• Do not "park" a lead by leaving it in a stage. Set a next action or close it.

STAGES: New → Contacted → Qualified → Discovery Scheduled → Discovery Completed → Proposal → Awaiting Signature/Payment → Submitted for Verification → Won / Lost. Each step has an entry rule; the system will tell you what is missing.

WEEKLY CHECK (10 minutes): (1) any follow-up overdue? (2) any lead with no next action? (3) any lead untouched for two weeks? Fix or close each one.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 5, $t$Working with Managers and Other Representatives$t$, ARRAY[$o$Know what a manager can and cannot see.$o$, $o$Ask for help without exposing other reps' leads.$o$]::text[], $b$Your manager can see your leads, activity and pipeline — that is what managers are for. Other representatives cannot see yours, and you cannot see theirs. If the system says a prospect is already being worked, you will not be told by whom; ask your manager to look into it.

What managers do NOT do: monitor your screen, track your location, or read your private messages. Nova's monitoring is limited to the activity you record inside the platform: leads, activities, stages, documents and training. There is no covert screen recording, device surveillance or location tracking.

Use your manager for: an unclear qualification, a prospect asking for something not available to sell, a discount request, a client who seems confused or upset, or anything that feels ethically off. Asking early is a strength.

SCRIPT to your manager: "I have a prospect at [business] who wants [thing]. The catalog shows it as [state]. Can we discuss whether a pilot or custom scope is possible, or how I should explain it's not available?"$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 1, $q$Which is an observable signal you can safely mention to a prospect?$q$, $c$["\"You are clearly losing half your leads.\"","\"Your staff obviously ignores calls.\"","\"Your competitors are crushing you.\"","\"Your Google listing shows a different phone number than your website.\""]$c$::jsonb, 3, $e$Observations you can point to are facts; claims about losses or staff are guesses.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 2, $q$What is the right way to note a signal?$q$, $c$["\"Website form errors — seen today on the Request a Quote page.\"","\"Seems disorganised.\"","\"They probably lose money.\"","\"Bad vibes.\""]$c$::jsonb, 0, $e$A good note says what you saw and where, so a manager can verify it.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 3, $q$Which source of contact details is acceptable?$q$, $c$["A purchased list of unknown origin","Guessing a personal email address","The business's own public website or listing, a referral or a person you met","Scraping social profiles in bulk"]$c$::jsonb, 2, $e$Contact details must come from legitimate channels the business or person made available.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 4, $q$You import a list of prospects. What does that do to consent for texting?$q$, $c$["It grants consent for texting","It grants consent for 30 days","It grants consent for email only","Nothing — importing never creates consent; texting needs the person's own recorded consent"]$c$::jsonb, 3, $e$Consent must be recorded from the person themselves; a rep cannot grant it on their behalf.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 5, $q$The system says a business is already being worked. What should you do?$q$, $c$["Contact the owner anyway, quickly","Use a different spelling of the business name","Ask your manager; do not try to work around the check","Ask other reps who has it"]$c$::jsonb, 2, $e$The duplicate check protects owners from being contacted by two people and protects each rep's leads.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 6, $q$What must a Qualified note contain?$q$, $c$["A short summary in your own words and whether you spoke with the decision maker (yes/no/unknown)","Only the business name","A guess at monthly revenue","A promise the owner made"]$c$::jsonb, 0, $e$Qualified must be something a manager can trust; both parts are required.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
