  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 8, $q$What does Nova monitor about a representative?$q$, $c$["Screen recordings of their computer","Their physical location throughout the day","Only the activity they record in the platform — leads, activities, stages, documents, training","Their personal messages"]$c$::jsonb, 2, $e$There is no covert screen recording, device surveillance or location tracking.$e$, false)
