    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 10, $q$A rep says "I'll just mark it Contacted; I'll call tomorrow." Why is that wrong?$q$, $c$["It is fine","Contacted can only be set by email","Only managers can mark Contacted","Contacted requires at least one real, logged outreach attempt"]$c$::jsonb, 3, $e$Stages must reflect what actually happened.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 1, 1, $t$Two neutral observations$t$, $p$Pick a real, public local business listing (do not contact them). Write two neutral, fact-based observations — each with where you saw it — that you could use to open a conversation. Then write the question each one lets you ask.$p$, $s$["Is each observation a fact you can point to?","Did you avoid guesses about lost customers or money?","Is each question open and neutral?"]$s$::jsonb, $m$Observation: the Google listing shows closing time 5 pm, the website says 6 pm (seen today). Question: "I noticed two different closing times — which is right, and do customers ever get confused?" Observation: the contact form page shows an error. Question: "When someone fills in your quote form, where does it go?"$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 2, 3, $t$Score three prospects$t$, $p$Take three prospects (real or fictional) and score each 0–1 on Problem, Authority, Timing, Reachability. Which do you contact first and why? Write a two-line qualification note for that one, including the decision-maker answer.$p$, $s$["Did you score each of the four criteria for each prospect?","Does your note say whether you spoke to the decision maker, honestly?","Is your reasoning about effort, not about revenue guesses?"]$s$::jsonb, $m$Prospect B scores 3/4 (observable listing conflict, owner reachable, new location opening) so I contact B first. Note: "Owner-run auto shop, new second location opening next month. Listing and website hours differ. Spoke with the owner. Decision maker: yes."$m$)
