  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 9, $q$You logged "meeting booked" but the prospect said "maybe". Why is that a problem?$q$, $c$["It isn't","Managers never read logs","It helps your numbers","Your manager plans around your pipeline and honest logging matters; \"maybe\" should be logged as what it was"]$c$::jsonb, 3, $e$Inflated outcomes mislead planning and harm trust.$e$, false)
