  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 1, 1, $t$Write your opener$t$, $p$Write a 3–4 sentence call opener for a real, public business (do not call). Include your name, the honest reason, one specific observation and permission to continue.$p$, $s$["Do you say who you are and why you are calling?","Is your observation specific and true?","Do you ask permission and leave room to say no?"]$s$::jsonb, $m$"Hi, this is Sam from Nova Systems. I look at how local businesses handle new customer inquiries. I noticed your listing shows two different phone numbers, and I wanted to ask which one customers should use. Do you have a minute?"$m$)
