  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 2, $q$You imported a list of numbers. Can you text them?$q$, $c$["Yes","No — importing never creates consent","Only at night","Yes if you add \"STOP\""]$c$::jsonb, 1, $e$Consent cannot be created by an import or by a rep.$e$, false)
