    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 1, 3, $t$Build a question ladder$t$, $p$Write five layered questions (situation, problem, impact, history, decision) for a discovery conversation with a local service business. For each, add one follow-up prompt.$p$, $s$["Are the questions open and non-leading?","Does any question supply a number or assume the answer?","Does each have a natural follow-up?"]$s$::jsonb, $m$1) "Walk me through what happens when a new customer contacts you." Follow-up: "What happens next?" 2) "What part of that doesn't work as well as you'd like?" Follow-up: "How often?" 3) "What does that mean for you day to day?" Follow-up: "How do you know?" 4) "What have you tried?" Follow-up: "What happened?" 5) "If something were worth changing, who would decide?" Follow-up: "How does that usually work?"$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 2, 4, $t$Sort said, observed and assumed$t$, $p$Read this: "The owner says calls after 5 go to voicemail. The listing says open till 6. I think he loses customers." Rewrite it as three labelled lines: Said / Observed / Assume (to check).$p$, $s$["Did you keep \"loses customers\" as an assumption to check?","Did you avoid adding any figure?"]$s$::jsonb, $m$Said: calls after 5 go to voicemail. Observed: the listing shows open until 6 pm. Assume (to check): some callers do not leave a message and may not call back.$m$)
