-- ---------------------------------------------------------------- follow-up-and-scheduling
DO $academy$
DECLARE pid uuid; can_write boolean;
BEGIN
  SELECT id, (content_review_status = 'pending_owner_review' OR version < 2) INTO pid, can_write FROM academy_programs WHERE slug = 'follow-up-and-scheduling';
  IF pid IS NULL THEN RAISE NOTICE 'program follow-up-and-scheduling not found — run academy-migration-standalone.sql first'; RETURN; END IF;
  IF NOT can_write THEN RAISE NOTICE 'program follow-up-and-scheduling content already approved — left unchanged'; RETURN; END IF;
  UPDATE academy_programs SET version = 2, content_review_status = 'pending_owner_review', learning_objectives = ARRAY[$o$Design a follow-up cadence that adds value and does not annoy.$o$, $o$Schedule conversations with minimal friction.$o$, $o$Handle no-shows, reschedules and silence.$o$, $o$Use next actions and reminders so nothing is forgotten.$o$]::text[],
    practical_prompt = NULL, practical_rubric = '[]'::jsonb WHERE id = pid;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 1, $t$The Follow-Up Mindset$t$, ARRAY[$o$Explain why most opportunities are lost to silence, not to no.$o$, $o$Follow up with purpose.$o$]::text[], $b$Most leads that go quiet are not saying no — they are busy. A good follow-up is a service: it makes it easy for a busy person to respond. A bad one is a nag. The difference is purpose. Before each follow-up, ask "What does this add?" — a clearer question, a helpful observation, a simpler way to reply, or a specific time offered.

PRINCIPLES:
• Every open lead has one next action with a date. That is your follow-up plan.
• Stay useful: reference the last conversation specifically.
• Vary the channel sensibly (email, call, message with consent) rather than repeating the same one.
• Stop gracefully: after a defined number of touches, close the loop with a polite note and set a longer-term check-in or close the lead.

WHAT NOT TO DO: send "just checking in" messages; guilt-trip ("I haven't heard back from you"); invent urgency; contact people who asked to stop; follow up more often than your manager's guidance.

EXAMPLE (fictional): After discovery, two days later: "Hi Dana — thanks for walking me through how calls are handled. As promised, here's what I understood: after-hours calls go to voicemail and get returned next morning. If that's right, the next step would be a written proposal — would Thursday at 10 suit to go through it?"$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 2, $t$A Cadence That Works$t$, ARRAY[$o$Plan touches across days.$o$, $o$Match cadence to lead stage.$o$]::text[], $b$A sensible baseline (your manager may adjust it):
• After a first conversation: a same-day thank-you and next-step note.
• If no reply: a follow-up in two to three business days; another about a week later; then a final closing note; then rest for several weeks.
• After a proposal is sent: check once after two or three days ("Did the proposal reach you? Happy to walk through it"); once more at about a week; then ask whether it makes sense to close the loop.
• After a signature: stay in touch on what happens next, but remember payment and verification are separate steps.

USE THE SYSTEM: set the next action and date after every touch; your Home screen lists overdue follow-ups and stale leads. Overdue follow-ups are visible to your manager — not as punishment, but so help can arrive.

SEASONAL AND TIMING SENSE: avoid Monday mornings and end of day Friday for many service businesses; ask them when they prefer to be contacted, and honour it.

CADENCE LIMITS: never contact the same person on the same day through multiple channels; never exceed the touches your manager sets; and always stop on request.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 3, $t$Scheduling Without Friction$t$, ARRAY[$o$Offer specific times.$o$, $o$Confirm and remind.$o$, $o$Record it correctly.$o$]::text[], $b$Scheduling is where good conversations die. Make it effortless:
1. OFFER TWO SPECIFIC TIMES, in their time zone. Not "when are you free?"
2. CONFIRM in writing: date, time, time zone, who will attend, how you will connect, how long.
3. SEND A REMINDER the day before, short and useful.
4. HAVE A FALLBACK: offer to reschedule in one message if something comes up.

EXAMPLE CONFIRMATION (approved wording): "Hi Dana — confirming Tuesday at 10:00 (Eastern) by phone, 20 minutes. I'll call you at the number I have. Reply if you'd like to move it."

REMINDER: "See you tomorrow at 10 — no preparation needed."

WHEN THE TIME IS SET, in the system: move to Discovery Scheduled with the real future date and time (the system requires it), and add a task or reminder for your preparation.

TIME ZONES: state them explicitly. If the client is in a different zone, write both.

IF A HELPFUL SCHEDULING TOOL IS APPROVED by Nova, use it; otherwise keep to email and phone. Do not send links to unknown tools.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 4, $t$No-Shows, Reschedules and Silence$t$, ARRAY[$o$Handle a missed appointment gracefully.$o$, $o$Reschedule kindly.$o$, $o$Know when to stop.$o$]::text[], $b$People miss appointments; it usually is not personal.

NO-SHOW: wait ten minutes, then send one message: "Hi Dana — I think we missed each other. No problem — would Thursday at 2 or Friday at 10 suit better?" If there is no reply, try once more in a couple of days by a different channel. Two tries, then set a longer check-in or close the lead with a reason.

RESCHEDULE REQUESTS: accept cheerfully; propose two new times; update the date in the system so your calendar and pipeline stay true.

CANCELLATIONS: thank them for the notice; ask if there's a better time, once; then respect the answer.

SILENCE AFTER A PROPOSAL: it is normal. Offer help once — "Would it help if I walked you through it?" — then leave space. Do not pressure. If the proposal expires, it is an opportunity to ask what would make sense, not to argue.

MARK LEADS HONESTLY: a lead that has gone silent for weeks with no reply is either given a dated long-term check-in or closed with a reason (for example no response). Do not leave zombie leads open.

KEEP YOUR DIGNITY: never send irritated messages. A calm, helpful tone today is why someone calls you in six months.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 5, $t$Reminders, Tasks and Weekly Rhythm$t$, ARRAY[$o$Use tasks and reminders.$o$, $o$Run a weekly review.$o$, $o$Keep an honest pipeline.$o$]::text[], $b$A simple weekly rhythm keeps you reliable:
• MONDAY: review overdue follow-ups, today's scheduled conversations, and leads with no next action; plan the week.
• DAILY: log activities as they happen; set a next action every time; do your scheduled calls first.
• FRIDAY: close dead leads with reasons; review what worked; note one improvement; check your training and documents for anything due.

TASKS vs REMINDERS: a task is something you must do (send a proposal); a reminder nudges you at a time. Both need a due date.

TIME BLOCKS: protect an hour a day for outreach when people are most reachable, and another for follow-ups and records.

WHAT YOUR MANAGER SEES: your leads, stages, overdue follow-ups and activity you recorded. They use it to help you, not to spy on you: there is no screen or location tracking.

SELF-CHECK QUESTIONS: Which lead did I forget? Which lead is ready for a proposal but has none? Which lead should I close? What one thing will I do better next week?$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 1, $q$What is the difference between a good follow-up and a nag?$q$, $c$["Frequency","The channel used","A good one adds something — clarity, an observation, a simpler way to reply, specific times","Length"]$c$::jsonb, 2, $e$Purpose separates service from pressure.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 2, $q$How should you offer meeting times?$q$, $c$["Two specific times in their time zone","\"When are you free?\"","Ask them to pick from a long list","Only one time, take it or leave it"]$c$::jsonb, 0, $e$Specific options reduce friction.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 3, $q$A prospect misses a scheduled call. What is the right first step?$q$, $c$["Send an angry message","Call five times","Close the lead","Wait ten minutes, then send one friendly message offering two new times"]$c$::jsonb, 3, $e$Assume good faith; make it easy.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 4, $q$What happens to a lead that has been silent for weeks?$q$, $c$["It stays open forever","Give it a dated long-term check-in or close it with a reason","Move it to Won","Delete it"]$c$::jsonb, 1, $e$Zombie leads hide the ones that matter.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 5, $q$For Discovery Scheduled, which is required?$q$, $c$["A signed contract","A real future date and time and a named contact","Manager approval","A price"]$c$::jsonb, 1, $e$Stage rules keep the pipeline honest.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 6, $q$A contact asked you to stop contacting them, and it is time for your follow-up. What do you do?$q$, $c$["Send it anyway","Email instead","Ask a colleague to send it","Do not contact; the flag is final"]$c$::jsonb, 3, $e$A request to stop overrides any cadence.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 7, $q$Which is an acceptable follow-up?$q$, $c$["\"Thanks for walking me through how calls are handled. Here's what I understood — is that right? Would Thursday at 10 suit to go through a proposal?\"","\"Just checking in!\"","\"Last chance — offer ends today!\"","\"Why haven't you replied?\""]$c$::jsonb, 0, $e$Specific, useful, easy to answer.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 8, $q$After sending a proposal, what is a sensible cadence?$q$, $c$["Daily calls","Never contact them","One check after two or three days, another at about a week, then ask whether to close the loop","Twice a day"]$c$::jsonb, 2, $e$Space and purpose.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 9, $q$Who sees your overdue follow-ups?$q$, $c$["Only you","The client","Every representative","You and your manager, so help can arrive"]$c$::jsonb, 3, $e$Managers see them to support you; other reps cannot see your leads.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 10, $q$A client reschedules twice. What is right?$q$, $c$["Refuse","Charge a fee","Accept kindly, update the date in the system, and if it continues ask once what would suit better","Close the lead immediately"]$c$::jsonb, 2, $e$Stay gracious, keep records true.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 1, 3, $t$Write the confirmation and reminder$t$, $p$Write the confirmation message and the day-before reminder for a 20-minute discovery call.$p$, $s$["Do both state date, time and time zone?","Is there an easy way to reschedule?","Do you say no preparation is needed?"]$s$::jsonb, $m$Confirmation: "Hi Dana — confirming Tuesday at 10:00 (Eastern) by phone, 20 minutes. I'll call the number I have. Reply if you'd like to move it." Reminder: "See you tomorrow at 10 — no preparation needed."$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 2, 4, $t$The no-show message$t$, $p$A prospect did not answer your scheduled call. Write your first message.$p$, $s$["Is it friendly and blame-free?","Does it offer two specific new times?"]$s$::jsonb, $m$"Hi Dana — I think we missed each other. No problem — would Thursday at 2 or Friday at 10 suit better?"$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
END
$academy$;

-- ---------------------------------------------------------------- crm-and-data-protection
DO $academy$
DECLARE pid uuid; can_write boolean;
BEGIN
  SELECT id, (content_review_status = 'pending_owner_review' OR version < 2) INTO pid, can_write FROM academy_programs WHERE slug = 'crm-and-data-protection';
  IF pid IS NULL THEN RAISE NOTICE 'program crm-and-data-protection not found — run academy-migration-standalone.sql first'; RETURN; END IF;
  IF NOT can_write THEN RAISE NOTICE 'program crm-and-data-protection content already approved — left unchanged'; RETURN; END IF;
  UPDATE academy_programs SET version = 2, content_review_status = 'pending_owner_review', learning_objectives = ARRAY[$o$Record leads, contacts and activities accurately in the Nova CRM.$o$, $o$Protect prospect and client data and Nova's confidential information.$o$, $o$Recognise sensitive data you must never collect or store.$o$, $o$Report mistakes and suspected breaches immediately.$o$]::text[],
    practical_prompt = NULL, practical_rubric = '[]'::jsonb WHERE id = pid;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 1, $t$Why Records Matter$t$, ARRAY[$o$Explain what the CRM is for.$o$, $o$Write factual, useful records.$o$]::text[], $b$The CRM is Nova's memory. It lets a manager help you, lets a colleague cover for you, protects you if a dispute arises, and is the basis for verification and commission. Records must be true, factual and useful.

GOOD RECORD: "Called 10:05, spoke with Dana (owner). She said after-hours calls go to voicemail and she returns them next morning. Asked for a 20-minute conversation; agreed Tuesday 10:00. Next action: send confirmation today."
BAD RECORD: "Good call, she loves us."

WHAT TO RECORD: date and time, channel, who you spoke to, what they said in their words, what you observed, the outcome, and the next action with a date.
WHAT NOT TO RECORD: guesses about money, personal opinions about people, health, family or other private details, and anything discriminatory.

ONE RECORD, NOT MANY: there is one CRM. Do not keep parallel spreadsheets or notes in personal apps with prospect data. If you need a private reminder, use the CRM's task or reminder feature.

ACCURACY BELONGS TO YOU: if you realise you recorded something wrong, correct it and add a note. Never edit history to look better.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 2, $t$Leads, Contacts, Stages and Duplicates$t$, ARRAY[$o$Use stages according to their entry rules.$o$, $o$Avoid duplicates and stolen leads.$o$, $o$Use lost reasons honestly.$o$]::text[], $b$Each lead is a business plus a contact plus a pipeline stage. The stages are New, Contacted, Qualified, Discovery Scheduled, Discovery Completed, Proposal, Awaiting Signature/Payment, Submitted for Verification, Won and Lost. Some you set yourself with evidence (Contacted needs a logged attempt; Qualified needs a summary and a decision-maker answer; Discovery Scheduled needs a future time; Discovery Completed needs real discovery notes). Others happen through their own steps (Proposal, Awaiting, Submitted, Won).

DUPLICATES: before creating a prospect, the system checks whether the business is already being worked; you will see a neutral message. Do not try to alter names, websites or phone numbers to slip past it. If it seems wrong, ask your manager.

LOST: choose a reason code and write what happened. You can reopen your own lost lead with a real reason, unless the contact asked not to be contacted or another rep now has the prospect.

DO-NOT-CONTACT: mark it the moment someone asks. Only the owner can clear it, and only with documented permission from the contact.

CONSENT FLAGS: you cannot set them. They come from the contact.

CHECK: before you close a lead as lost, ask "Is my reason true and complete?" A vague reason hurts your manager's ability to help.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 3, $t$Protecting Data$t$, ARRAY[$o$Handle personal and business data carefully.$o$, $o$Never collect sensitive identifiers.$o$, $o$Use approved tools and channels only.$o$]::text[], $b$You will handle names, phone numbers, emails, business details and notes. Protect them:
• NEVER collect or store: social security numbers, government ID numbers, driver's licence details, bank account or routing numbers, card numbers, passwords, tax identifiers. If a person volunteers one, tell them not to, do not write it down, and tell your manager if it was sent to you in writing.
• Use only Nova-approved tools; do not copy lead data into personal notes, chat apps or unapproved spreadsheets; do not forward lead data to personal email.
• Log in only on devices you control; never share your login; use a strong password; sign out on shared computers.
• Do not discuss one client's or prospect's information with another. Do not post about clients on social media.
• Confidential Nova information (pricing decisions, commission plans, internal documents) stays inside Nova.
• Keep screens private in public places.

CLIENT PAYMENTS: card or bank details are entered only on the payment provider's hosted page. You never see or store them.

PROSPECT RIGHTS: if a person asks what you hold about them or asks to be deleted, do not promise anything you cannot do; tell your manager, who will handle it through Nova's process.

CHECK: If this data was leaked, could it harm someone? If yes, it needs extra care.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 4, $t$Documents, Signatures and Records of Consent$t$, ARRAY[$o$Understand your own agreements and their versions.$o$, $o$Sign only what you have read.$o$, $o$Know what stays private.$o$]::text[], $b$In Nova you will sign agreements electronically: the working agreement, compensation schedule, confidentiality and acceptable-use policies. Each is a specific version; if Nova changes one materially, you must sign the new version.

HOW SIGNING WORKS: open the document (this is recorded), read it, agree to sign electronically, type your full name (and optionally draw your signature), and submit. The server records the time, the version and a fingerprint of what you signed. You can download a copy. Nova countersigns some documents. Ask questions before you sign; do not sign something you do not understand.

WHAT STAYS PRIVATE: your signed documents, your compensation details and your application are visible to you, your manager and Nova's owner as needed — not to other representatives. Do not share them.

CLIENT SIGNATURES: clients sign proposals through a personal link. You cannot sign for a client, cannot mark a signature as genuine, and must never pressure a client to sign quickly. If a client says they signed offline, submit it with detailed evidence — the owner must verify it.

RETENTION: do not delete records to hide mistakes. Nova keeps history so that everything can be reviewed fairly.

BEFORE YOU SIGN: (1) Have I read it? (2) Do I understand the compensation and conditions? (3) Have I asked about anything unclear?$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 5, $t$Mistakes, Incidents and Reporting$t$, ARRAY[$o$Report errors and suspected breaches at once.$o$, $o$Understand that early reporting is protected.$o$]::text[], $b$Mistakes happen. What matters is how quickly you report them. Tell your manager immediately if you: sent a message to the wrong person; contacted someone who asked to stop; received or stored sensitive information; lost a device with Nova access; clicked something suspicious; noticed someone else's data you should not see; or believe an account has been misused.

WHAT TO DO: (1) stop; (2) do not try to hide or fix it silently; (3) write down what happened factually; (4) tell your manager; (5) follow their instructions.

NO PUNISHMENT FOR EARLY, HONEST REPORTING: the aim is to protect people. Concealment is what creates serious problems.

PHISHING AND IMPERSONATION: Nova will never ask you by message for your password, payment codes or to change payout details. If you receive such a request, report it.

SUSPENDED ACCOUNTS: if your access is suspended, do not try to work around it; contact your manager. Your history is kept.

MONITORING: Nova looks at what you record in the platform. It does not record your screen, track your location or read personal messages.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 1, $q$Which is the best CRM note?$q$, $c$["\"Good call, she loves us.\"","\"Called 10:05, spoke with Dana (owner). After-hours calls go to voicemail; she returns them next morning. Agreed Tuesday 10:00. Next: send confirmation.\"","\"Probably losing money.\"","\"Try again.\""]$c$::jsonb, 1, $e$Factual, specific, with a next action.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 2, $q$A prospect volunteers their social security number. What do you do?$q$, $c$["Write it in the notes","Ask them to email it","Tell them not to share it, do not record it, and tell your manager if it arrived in writing","Store it in a spreadsheet"]$c$::jsonb, 2, $e$Sensitive identifiers are never collected in sales.$e$, true)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 3, $q$Where may you enter a client's card details?$q$, $c$["Only on the payment provider's hosted payment page — never in Nova systems or notes","In an email to yourself","In the CRM notes","In a spreadsheet"]$c$::jsonb, 0, $e$Nova and reps never see or store card data.$e$, true)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 4, $q$The system says a business is already being worked. What do you do?$q$, $c$["Change the website spelling and retry","Contact them anyway","Use another rep's account","Ask your manager; never try to bypass the check"]$c$::jsonb, 3, $e$The check protects owners and other reps.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 5, $q$You made an error in a record. What now?$q$, $c$["Delete the record","Correct it and add a note; never rewrite history to look better","Ignore it","Blame a colleague"]$c$::jsonb, 1, $e$Records are honest; history is kept.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 6, $q$Where may you keep lead data?$q$, $c$["A personal notes app","Only in the Nova CRM and Nova-approved tools","Personal email","A shared public document"]$c$::jsonb, 1, $e$One CRM; no personal copies.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 7, $q$Someone emails claiming to be Nova and asks for your password. What do you do?$q$, $c$["Send it","Forward it to a colleague","Reply asking why","Do not; report it to your manager — Nova never asks for passwords by message"]$c$::jsonb, 3, $e$Phishing and impersonation must be reported.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 8, $q$A client says they signed a paper copy. How do you record the sale?$q$, $c$["Submit it for verification with detailed evidence; the owner must verify","Mark it Won","Sign it yourself","Ignore it"]$c$::jsonb, 0, $e$Only verified signatures count; reps cannot mark them genuine.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 9, $q$What does Nova monitor about you?$q$, $c$["Screen, location and messages","Your personal phone","Only the activity you record in the platform","Nothing at all"]$c$::jsonb, 2, $e$No covert surveillance.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 10, $q$You realise you emailed a prospect who had asked to stop. What do you do?$q$, $c$["Hope they don't notice","Send an apology every day","Delete the email","Tell your manager right away, write down what happened, and make sure the flag is set"]$c$::jsonb, 3, $e$Early honest reporting protects everyone.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 1, 1, $t$Rewrite a weak note$t$, $p$Rewrite this into a good CRM note: "Talked to the owner, seems interested, they lose a lot of business, follow up soon." Use only facts you would plausibly know from a real conversation (invent plausible neutral details clearly as an example).$p$, $s$["Does it include date, channel, who and what was said?","Did you remove guesses about losses?","Is there a dated next action?"]$s$::jsonb, $m$"Called Tue 10:05, spoke with Dana (owner). She said after-hours calls go to voicemail and she calls back next morning. She agreed to a 20-minute conversation Thu 10:00. Next action: send confirmation today."$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 2, 3, $t$What do you do with this?$t$, $p$A client emails you a photo of their driver's licence "to prove who they are." What are your next three steps?$p$, $s$["Do you avoid saving or forwarding it?","Do you tell your manager?","Do you reply explaining Nova does not need it?"]$s$::jsonb, $m$1) Do not save, forward or store it. 2) Tell your manager right away so it is handled properly. 3) Reply kindly: "Thanks — we don't need identification documents. Please don't send any; we'll confirm details another way."$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
END
$academy$;

-- ---------------------------------------------------------------- ethics-commission-final-assessment
DO $academy$
DECLARE pid uuid; can_write boolean;
BEGIN
  SELECT id, (content_review_status = 'pending_owner_review' OR version < 2) INTO pid, can_write FROM academy_programs WHERE slug = 'ethics-commission-final-assessment';
  IF pid IS NULL THEN RAISE NOTICE 'program ethics-commission-final-assessment not found — run academy-migration-standalone.sql first'; RETURN; END IF;
  IF NOT can_write THEN RAISE NOTICE 'program ethics-commission-final-assessment content already approved — left unchanged'; RETURN; END IF;
  UPDATE academy_programs SET version = 2, content_review_status = 'pending_owner_review', learning_objectives = ARRAY[$o$Apply Nova's sales ethics to real situations.$o$, $o$Explain how commission works as a process — plan, conditions, verification, approval, payout — without assuming any rate.$o$, $o$Show consistent judgment across everything in the Academy.$o$, $o$Handle critical-compliance questions correctly.$o$]::text[],
    practical_prompt = NULL, practical_rubric = '[]'::jsonb WHERE id = pid;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 1, $t$Nova's Sales Ethics in One Page$t$, ARRAY[$o$State the core rules.$o$, $o$Apply them under pressure.$o$]::text[], $b$The core rules, everywhere and always:
1. TELL THE TRUTH. No guarantees, no invented figures, no fake case studies, no pretending.
2. DIAGNOSE BEFORE YOU PRESCRIBE. Ask, listen, record, then propose.
3. RESPECT PEOPLE'S "NO". Stop when asked, mark it, do not return without an invitation.
4. COLLECT NO SENSITIVE IDENTIFIERS. Never government IDs, tax IDs, bank or card numbers.
5. QUOTE ONLY WHAT IS APPROVED. Prices, timelines, terms and offerings come from what the owner approved.
6. LET THE SYSTEM BE THE RECORD. Do not claim a close, a signature or a payment the system has not recorded.
7. DO NOT WORK AROUND CONTROLS. Do not bypass duplicate checks, stage rules, approvals or permissions.
8. SPEAK UP. Tell your manager when something feels wrong.

UNDER PRESSURE: a hard month, a demanding client or a tempting shortcut is exactly when these rules matter. If a shortcut would make you uncomfortable if the owner watched, it is the wrong shortcut.

SCENARIO: a client says "I'll sign today if you guarantee I'll get twice the customers." Correct response: "I can't promise that and I wouldn't trust anyone who did. What I can promise is a clear written scope and that we'll show you what we find with evidence. Would you like me to send the proposal to review?" Then stop pressing.

REMEMBER: the company you represent is trusted because its people are honest. Every honest "I don't know" is an investment in that trust.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 2, $t$How Commission Works — the Process$t$, ARRAY[$o$Trace a commission from sale to payout.$o$, $o$Explain conditions and who approves what.$o$, $o$Avoid assuming any rate or promising pay.$o$]::text[], $b$THIS LESSON TEACHES THE PROCESS, NOT THE NUMBERS. Rates and conditions come only from the commission plan the owner has approved; if you are told a rate by anyone else, it is not authoritative. Never state or promise a rate to anyone.

THE PATH:
1. You submit a closed sale for verification. The system may show an ESTIMATED commission if an approved plan exists. Estimated commission is not earned; it can change or be cancelled.
2. The owner VERIFIES the sale. The entry becomes PENDING CONDITIONS.
3. CONDITIONS are those in your approved plan — for example that the client's payment has been received, and any hold-back period the plan defines. When they are met the entry becomes ELIGIBLE.
4. Finance/owner APPROVES eligible entries (OWNER APPROVED). You cannot approve your own.
5. The owner approves a concrete PAYOUT BATCH; entries become SCHEDULED.
6. Payment is made. It becomes PAID only when a payment provider confirms it or the owner records an external payment with evidence (labelled as recorded by Nova, not provider-confirmed).

IF SOMETHING GOES WRONG: a refund or dispute before payment reverses the entry; after payment it creates an adjustment that the owner decides, never a silent deduction. A failed payout shows as Failed and is retried by the owner.

YOUR EARNINGS SCREEN keeps Estimated, Pending, Eligible, Approved and Paid separate. Do not add them together and call it income.

YOU MAY NOT: change your commission, approve it, record a payment, or promise anyone pay. Questions go to your manager or the owner.

PAYOUT ACCOUNT: if payouts go through a provider, you complete a provider-hosted onboarding page; Nova never sees your bank details.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 3, $t$Conflicts of Interest, Gifts and Honesty With Clients$t$, ARRAY[$o$Recognise conflicts.$o$, $o$Handle gifts and side deals.$o$, $o$Stay honest when it costs you.$o$]::text[], $b$Conflicts of interest arise when a personal interest could influence your judgment for Nova or a client. Examples: selling to a friend or family member's business without telling your manager; taking a payment or gift from a client; steering a client to a decision because of how you would be paid; offering a side deal outside Nova's system.

RULES:
• Disclose any personal connection to a prospect before working the lead.
• Do not accept gifts beyond token courtesy; never accept money or favours.
• Do not make private arrangements with a client outside the platform, including payment.
• Do not discourage a client from something that would be good for them because it pays you less.
• Do not discuss commission with clients or promise anything about how you are paid.

WHEN YOU MAKE A MISTAKE WITH A CLIENT: tell them honestly and tell your manager. A fixed mistake is forgiven; a hidden one is not.

WHEN A CLIENT WOULD BE BETTER OFF WITHOUT US: say so. Nova's reputation grows from clients who were told the truth.

DO NOT SELL WHAT DOES NOT EXIST: if an offering is not available, do not sell it, even if the client would pay. Ask your manager about an owner-approved pilot or custom scope.

SCENARIO: a friend's restaurant wants a discount because "we're friends." Correct response: disclose the connection to your manager, request any discount through the system with an honest reason, and let the owner decide.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 4, $t$Putting It All Together: Case Studies$t$, ARRAY[$o$Apply the Academy to end-to-end scenarios.$o$, $o$Identify errors and better choices.$o$]::text[], $b$Read each case, decide what you would do, then compare.

CASE 1 — "Free pilot, testimonial required." A client wants a discount; a colleague suggests "free pilot if they give us a glowing testimonial." Correct: do not. Discounts and pilots are owner decisions, and testimonial-for-discount arrangements are not allowed. Request the discount through the system with an honest reason.

CASE 2 — Paper signature. A client hands you a signed paper agreement. Correct: do not mark anything won. Submit for verification with detailed evidence; the owner verifies. Do not scan or upload identity documents.

CASE 3 — Missed quota pressure. It is the last day of the month; a lead says "maybe next week." Correct: log it truthfully; do not submit a sale that has not closed; do not invent urgency.

CASE 4 — Text without consent. A contact gave their mobile number on the phone. Correct: confirm by email or ask for consent on the call so it is recorded; do not text until it is.

CASE 5 — Delayed audit. A client asks "When will I get the audit?" and no turnaround is approved. Correct: "I'll confirm the timing and get back to you" — then ask your manager. Do not quote 24 or 72 hours unless the owner has approved that statement in the toolkit.

CASE 6 — Wrong send. You emailed a proposal to the wrong address. Correct: tell your manager immediately; recall the proposal so the link stops working; do not hide it.

CASE 7 — Client asks for a price you don't have. Correct: the scope decides it; a written proposal will contain the price; only approved prices are quoted.

Use these cases as a self-test before the final assessment.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_lessons (program_id, order_index, title, objectives, body) VALUES (pid, 5, $t$Final Assessment: What to Expect$t$, ARRAY[$o$Understand the rules of the final assessment.$o$, $o$Know how critical questions work.$o$]::text[], $b$The final assessment covers the whole Academy. It is graded by the server against a stored answer key you never see; your score, the pass mark, and the number of attempts follow the Academy policy the owner has approved. If that policy is still pending, results are shown as provisional and the certificate will say so.

CRITICAL QUESTIONS test the rules that must never be broken: stopping when asked, never collecting sensitive identifiers, never guaranteeing results, never quoting unapproved prices, and never claiming a sale the system has not recorded. If you miss a critical question you cannot pass on score alone. A reviewer will look at the result and talk with you; the owner decides whether you retake or can proceed. This is not a punishment — it is how Nova makes sure the essentials are understood.

PRACTICAL ASSESSMENTS in Programs 6 and 7 must be approved by a reviewer before you can be certified in those programs. Completing training never activates an account: activation is a separate decision by the owner after your agreements are signed and setup is verified.

HOW TO PREPARE: re-read the lessons you found hardest; redo the exercises; walk through the seven cases; ask your manager about anything you are unsure of. Do not memorise answers — the questions test judgment.

CERTIFICATES: when you complete a program you can download an internal Nova certificate with a unique ID. Anyone can verify its validity with the verification code. It is a Nova training record — not an accredited or third-party credential and not an authorisation to act for Nova.$b$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET title = EXCLUDED.title, objectives = EXCLUDED.objectives, body = EXCLUDED.body;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 1, $q$A client says "I'll sign today if you guarantee twice the customers." What do you say?$q$, $c$["\"I can't promise that; what I can offer is a clear written scope and evidence-based findings. Shall I send the proposal to review?\"","\"I guarantee it.\"","\"Yes, probably.\"","\"Sign now and I'll make it happen.\""]$c$::jsonb, 0, $e$Never guarantee results.$e$, true)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 2, $q$A contact tells you to stop contacting them. What do you do?$q$, $c$["Finish your pitch","Stop, mark do-not-contact, and do not contact again","Send one more email","Ask a colleague to try"]$c$::jsonb, 1, $e$A request to stop is final.$e$, true)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 3, $q$A client offers to email a photo of their government ID "for verification". What do you do?$q$, $c$["Accept and store it","Ask them to also send a bank statement","Decline; sales never collects government or tax identifiers; tell your manager if it was sent","Forward it to the owner"]$c$::jsonb, 2, $e$Sensitive identifiers are never collected.$e$, true)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 4, $q$A client asks the price of an offering that has no approved price. What do you do?$q$, $c$["Say the scope decides it, and that a written proposal will show the price; do not quote an unapproved figure","Quote what you think","Guess a range","Say it is free"]$c$::jsonb, 0, $e$Only approved prices.$e$, true)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 5, $q$A client says they signed a paper agreement. What do you do?$q$, $c$["Mark the lead Won","Ignore it","Sign for them","Submit it for verification with detailed evidence and let the owner verify; never mark it won or genuine yourself"]$c$::jsonb, 3, $e$Reps cannot mark signatures genuine or sales won.$e$, true)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 6, $q$Where does the commission rate come from?$q$, $c$["Your manager's promise","Only the commission plan the owner has approved","A colleague","What you estimate"]$c$::jsonb, 1, $e$Never assume or state a rate.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 7, $q$An estimated commission is…$q$, $c$["Earned","Not earned; it can change or be cancelled","Guaranteed","Paid"]$c$::jsonb, 1, $e$Estimated ≠ earned.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 8, $q$When does a commission become "Paid"?$q$, $c$["When you say so","When it is eligible","When the client signs","When a payment provider confirms it, or when the owner records an externally made payment with evidence (labelled as recorded by Nova)"]$c$::jsonb, 3, $e$No button manufactures success.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 9, $q$A client refunds after your commission was paid. What happens?$q$, $c$["An adjustment is recorded and the owner decides; it is never a silent deduction","Nothing","You must repay immediately","The client is charged"]$c$::jsonb, 0, $e$Clawbacks are explicit owner decisions.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 10, $q$You are related to a business owner you would like to sell to. What do you do?$q$, $c$["Sell quietly","Give a private discount","Disclose to your manager before working the lead and let them decide","Sell outside the platform"]$c$::jsonb, 2, $e$Disclose conflicts of interest first.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 11, $q$A client asks "When will I get the audit?" and no turnaround is approved. What do you say?$q$, $c$["\"24 hours.\"","\"72 hours.\"","\"Immediately.\"","\"I'll confirm the timing and get back to you.\""]$c$::jsonb, 3, $e$Turnaround times must be approved before they are promised.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_quiz_questions (program_id, order_index, question, choices, correct_index, explanation, critical) VALUES (pid, 12, $q$Training is complete and all your quizzes are passed. What happens to your account?$q$, $c$["It is activated automatically","You can start selling anyway","Nothing automatically: the owner activates it after agreements are signed and setup is verified","The manager activates it"]$c$::jsonb, 2, $e$Training never activates an account.$e$, false)
    ON CONFLICT (program_id, order_index) DO UPDATE SET question = EXCLUDED.question, choices = EXCLUDED.choices, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, critical = EXCLUDED.critical;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 1, 2, $t$Explain commission to a friend$t$, $p$A friend asks how you get paid. Write a short, honest answer that does not state any rate or promise any amount.$p$, $s$["Did you avoid numbers and promises?","Did you describe verification and conditions?","Did you say it comes from the owner-approved plan?"]$s$::jsonb, $m$"I'm paid a commission under a plan Nova has approved. A sale has to be verified and the client's payment received before it becomes eligible, then it's approved and paid. I can't promise any amount — it depends on real, verified sales."$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
  INSERT INTO academy_exercises (program_id, order_index, lesson_order, title, prompt, self_check, model_answer) VALUES (pid, 2, 4, $t$Choose your response$t$, $p$Pick two of the seven cases and write in two sentences what you would do and why.$p$, $s$["Do your choices follow the ethics rules?","Did you say who you would tell (manager/owner)?"]$s$::jsonb, $m$Case 4: I would confirm by email and ask for consent on the call so it is recorded, because texting without recorded consent is not allowed. Case 6: I would tell my manager at once and recall the proposal so the link stops working, because hiding it would be worse.$m$)
    ON CONFLICT (program_id, order_index) DO UPDATE SET lesson_order = EXCLUDED.lesson_order, title = EXCLUDED.title, prompt = EXCLUDED.prompt, self_check = EXCLUDED.self_check, model_answer = EXCLUDED.model_answer;
END
$academy$;

-- ---------------------------------------------------------------- Sales Toolkit starter items (ALL DRAFT — owner approves each)
INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'script', $t$Cold call opener$t$, $b$"Hi, this is [your name] from Nova Systems. I look at how local businesses handle new customer inquiries. I noticed [one specific, true observation]. Do you have a minute, or is now a bad time?"

If busy: "Understood — when would be better for two minutes?" (Set the callback as a dated next action.)
If they say stop: "Understood — I won't contact you again. Sorry for the interruption." (Mark do-not-contact.)$b$, 'cold-calling', $n$Identify yourself honestly; no claims or figures.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'script' AND title = $t$Cold call opener$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'script', $t$Voicemail (under 25 seconds)$t$, $b$"Hi [name], this is [your name] from Nova Systems, [your real number]. I look at how local businesses handle new inquiries and noticed something on your listing I wanted to ask about. I'll try you again [day and part of day]. If you'd rather I didn't, just say so and I won't."$b$, 'cold-calling', $n$No figures, no promises.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'script' AND title = $t$Voicemail (under 25 seconds)$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'script', $t$In-person opener$t$, $b$"Hi, I'm [your name] from Nova Systems. I'm not selling anything today — I look at how local businesses handle new customer inquiries, and I noticed [observation]. Who would be best to ask, if now isn't a bad time?"

If busy: "I can see you're busy — could I come back [specific time]?" If asked to leave: "Of course, thank you." Leave immediately.$b$, 'in-person-sales', $n$Never remain after being asked to leave.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'script' AND title = $t$In-person opener$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'script', $t$Discovery conversation — question ladder$t$, $b$Framing: "I'd like to ask some questions about how new customers reach you and what happens next. I'm not here to pitch — afterwards I'll tell you honestly whether a closer look would be useful. Is that okay?"

1. Walk me through what happens when a new customer contacts you.
2. What part of that doesn't work as well as you'd like?
3. What does that mean for you day to day? (Record their words; do not supply a figure.)
4. What have you tried? What happened?
5. If something were worth changing, who would decide, and how?

Follow-ups: "Tell me more." "What happens next?" "How often?" "How do you know?"
Close: summarise back; say honestly whether a closer look is worthwhile; propose one small next step.$b$, 'discovery-and-diagnostic-selling', $n$Diagnose before prescribing; record said / observed / assumed separately.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'script' AND title = $t$Discovery conversation — question ladder$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'email_template', $t$Cold email — first touch$t$, $b$Subject: [specific observation, e.g. "Two phone numbers on your listing"]

Hi [name] — I noticed [one specific, true observation and where you saw it]. Customers may not know [plain-words consequence, no numbers]. I look at how local businesses handle new inquiries and write down what I find. Would a 15-minute call [two specific times] be useful?

If not, just reply "no thanks" and I won't email again.

— [your name], Nova Systems$b$, 'cold-emailing', $n$One ask, one true observation, an easy opt-out. Do not add claims or figures.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'email_template' AND title = $t$Cold email — first touch$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'email_template', $t$Cold email — follow-up$t$, $b$Subject: Re: [same subject as first email — only if it was a real earlier email from you]

Hi [name] — following up on [the observation]. [One additional observation or a clearer question.] If it would help to talk for 15 minutes, tell me a time that suits you; if it's already sorted, no need to reply.

— [your name]$b$, 'cold-emailing', $n$Only reuse "Re:" for a genuine earlier email from you. Three touches at most.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'email_template' AND title = $t$Cold email — follow-up$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'email_template', $t$Closing note (last touch)$t$, $b$Hi [name] — I'll stop here so I don't clutter your inbox. If handling new inquiries ever becomes a priority, I'm happy to look at it with you. Thanks for your time.

— [your name], Nova Systems$b$, 'follow-up-and-scheduling', $n$Set a long-term check-in or close the lead with a reason.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'email_template' AND title = $t$Closing note (last touch)$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'email_template', $t$Meeting confirmation$t$, $b$Hi [name] — confirming [day] at [time] ([time zone]) by [phone / video / in person], about [20] minutes. I'll bring a few questions; there's nothing to prepare. Reply if you'd like to move it.

— [your name], Nova Systems$b$, 'follow-up-and-scheduling', $n$Always state the time zone.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'email_template' AND title = $t$Meeting confirmation$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'email_template', $t$Thank-you after discovery$t$, $b$Hi [name] — thank you for walking me through how [business] handles new inquiries. As I understood it: [two or three of their own points]. If that's right, the sensible next step would be [written proposal / a closer look]. Would [two times] suit to go through it?

— [your name]$b$, 'discovery-and-diagnostic-selling', $n$Reflect their words; promise no outcome.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'email_template' AND title = $t$Thank-you after discovery$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'email_template', $t$Proposal cover note$t$, $b$Hi [name] — the proposal is on its way through Nova's system. It sets out exactly what is included and the price. Please read it in full; you can sign online, and I'm happy to walk through it before you decide. Payment is taken on Nova's secure payment page after you sign — I never handle payment details.

— [your name]$b$, 'discovery-and-diagnostic-selling', $n$The price appears only in the proposal, from approved pricing.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'email_template' AND title = $t$Proposal cover note$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'sms_template', $t$Text confirmation (only with recorded consent)$t$, $b$Hi [name], this is [your name] from Nova Systems. Confirming [day] at [time]. Reply STOP to opt out.$b$, 'cold-messaging', $n$Send ONLY if the contact has given recorded consent to be texted. Include identification and opt-out.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'sms_template' AND title = $t$Text confirmation (only with recorded consent)$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'message_template', $t$First DM to a business page$t$, $b$Hi — [your name] from Nova Systems. I noticed [specific, true observation]. [One easy question]? I look at how local businesses handle new inquiries and thought it was worth flagging.$b$, 'cold-messaging', $n$Two to four lines. No hype, no figures.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'message_template' AND title = $t$First DM to a business page$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'message_template', $t$Reply to "Who is this?"$t$, $b$[Your name] from Nova Systems — I look at how local businesses handle new customer inquiries. Sorry for the surprise; I noticed [observation] and thought I'd flag it. Happy to leave it there if you'd rather.$b$, 'cold-messaging', $n$Offer an easy out.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'message_template' AND title = $t$Reply to "Who is this?"$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'checklist', $t$Before you contact anyone$t$, $b$☐ Do I have a specific, true reason to contact THIS business?
☐ Am I allowed to contact this person this way (consent for texts; not do-not-contact)?
☐ Is anything in my message untrue or unprovable?
☐ Does it avoid guarantees, figures, unapproved prices and unapproved turnaround?
☐ Will I log it, with a next action and date?$b$, 'nova-fundamentals', $n$Use before every outreach.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'checklist' AND title = $t$Before you contact anyone$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'checklist', $t$Qualification checklist$t$, $b$Score 0 or 1 each:
☐ PROBLEM — an observable sign of a gap (where did I see it?)
☐ AUTHORITY — am I speaking with someone who can say yes?
☐ TIMING — any reason to act soon?
☐ REACHABILITY — do they respond through any channel?

Record: a one- or two-sentence summary in your own words, and decision maker: yes / no / unknown (honestly).$b$, 'prospecting-and-qualification', $n$Required to move a lead to Qualified.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'checklist' AND title = $t$Qualification checklist$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'checklist', $t$CRM logging checklist$t$, $b$☐ Date and time, channel, who I spoke to
☐ What they said (their words) and what I observed
☐ Outcome (from the list)
☐ Next action with a date
☐ No sensitive identifiers, no guesses about money, no private details
☐ Do-not-contact set if anyone asked to stop$b$, 'crm-and-data-protection', $n$Factual, useful, honest.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'checklist' AND title = $t$CRM logging checklist$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'checklist', $t$Do-not-contact protocol$t$, $b$1. Say: "Understood — I'll take you off my list and won't contact you again. Sorry for the interruption."
2. Mark do-not-contact on the lead immediately.
3. Add a factual note of what was said.
4. Do not try one more pitch. Do not ask a colleague to call.
5. Only the owner can clear the flag, with documented written permission from the contact.$b$, 'crm-and-data-protection', $n$Final and immediate.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'checklist' AND title = $t$Do-not-contact protocol$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'objection', $t$Objection: "We're not interested"$t$, $b$"That's fair. Can I ask what's working well for you with new customers at the moment? I only reach out when I notice something specific, and I may have got it wrong."
If still no: thank them and end. Log it factually.$b$, 'cold-calling', $n$Accept a genuine no.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'objection' AND title = $t$Objection: "We're not interested"$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'objection', $t$Objection: "We already have an agency"$t$, $b$"Good — Nova doesn't replace that. We look at how inquiries are actually handled and write down what we find; sometimes the answer is that you're fine. Would that be useful as a second opinion?"$b$, 'cold-calling', $n$Do not criticise the existing provider.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'objection' AND title = $t$Objection: "We already have an agency"$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'objection', $t$Objection: "How much does it cost?"$t$, $b$"The scope decides it, so I won't guess. After a short conversation I can bring a written proposal so you can see exactly what it covers and what it costs."
Only quote a price shown as approved in the Product Catalog. If none, use the sentence above.$b$, 'discovery-and-diagnostic-selling', $n$Never quote an unapproved price.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'objection' AND title = $t$Objection: "How much does it cost?"$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'objection', $t$Objection: "Will it work? Can you guarantee results?"$t$, $b$"I can't promise a result, and I'd be wary of anyone who does. What I can do is show you what's actually happening today, with evidence, so you can decide what's worth fixing."$b$, 'in-person-sales', $n$No guarantees.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'objection' AND title = $t$Objection: "Will it work? Can you guarantee results?"$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'objection', $t$Objection: "How long will the audit take?"$t$, $b$If the owner has approved audit terms they appear in Product Catalog → Audit terms; use exactly that sentence.
If not: "I'll confirm the timing and get back to you." Then ask your manager.$b$, 'nova-fundamentals', $n$A turnaround is never promised unless the owner approved it.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'objection' AND title = $t$Objection: "How long will the audit take?"$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'faq', $t$What may I say about the offerings?$t$, $b$Use the Product Catalog. Each offering shows its readiness label. Only Available for Sale (or a Pilot with the owner's pilot terms) may appear in a proposal. If an offering is Draft, Internal Test or Paused, say it isn't available to sell yet and ask your manager whether a pilot or custom scope is possible. Descriptions, what is included and excluded, and discovery questions are in the catalog entry.$b$, 'nova-fundamentals', $n$The catalog is the source of truth.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'faq' AND title = $t$What may I say about the offerings?$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'guide', $t$How a sale becomes real$t$, $b$Five separate facts, each recorded by its own step: (1) rep-reported close, (2) client signed through Nova, (3) payment received (provider event or owner-recorded evidence), (4) owner-verified sale, (5) fulfilment started. You can only do (1). Commission follows the owner-approved plan: Estimated → Pending Conditions → Eligible → Owner Approved → Scheduled → Paid. Estimated is not earned.$b$, 'ethics-commission-final-assessment', $n$Describes process only; no rates.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'guide' AND title = $t$How a sale becomes real$t$);

INSERT INTO sales_toolkit_items (kind, title, body, program_slug, compliance_note, status)
SELECT 'guide', $t$What to do if you make a mistake$t$, $b$Stop. Do not hide or silently fix it. Write down what happened factually. Tell your manager immediately. Follow their instructions. Examples: message sent to the wrong person, contact who asked to stop was contacted, sensitive information received, suspicious link clicked, device lost.$b$, 'crm-and-data-protection', $n$Early honest reporting protects everyone.$n$, 'draft'
WHERE NOT EXISTS (SELECT 1 FROM sales_toolkit_items WHERE kind = 'guide' AND title = $t$What to do if you make a mistake$t$);
